      "detail": "错误表现：笔画出现侧锋（字幕作「册封」「侧封」）或角锋（字幕作「角封」「角峰」）；尤其是笔画转折处出现尖角、像拧麻花。原因：毛笔搅在一起了——毛笔一沾黑、笔画也是黑，两者重合就看不出笔锋封面的变化；搅在一起后每个笔毛方向都不一样，成了螺旋状。老师的判据与改法：出现侧锋的问题 99% 都是没有抬笔；停顿（节点）时就要把笔稍微抬起来，为下一个动作做准备。另外笔画过粗、按死，也会「写着写着就搅在一起」。",
